class Item extends RefCounted:
	var value: int
	func _init(p_value: int = 10) -> void:
		value = p_value


func run() -> int:
	var a := Item.new()
	var b := Item.new(25)
	return a.value + b.value

class HealthTracker extends RefCounted:
	var hp: int = 100:
		set(value):
			hp = clampi(value, 0, 100)


func run() -> int:
	var tracker := HealthTracker.new()
	tracker.hp = 150
	var val1 := tracker.hp
	tracker.hp = -20
	var val2 := tracker.hp
	return val1 + val2

class ScoreCard extends RefCounted:
	var points: int = 0
	static func create_bonus(base: int) -> ScoreCard:
		var card := ScoreCard.new()
		card.points = base * 2
		return card


func run() -> int:
	var card := ScoreCard.create_bonus(15)
	return card.points

class StepCounter extends RefCounted:
	var _steps: int = 0
	func step() -> void:
		_steps += 2
	func get_steps() -> int:
		return _steps


func run() -> int:
	var counter := StepCounter.new()
	counter.step()
	counter.step()
	counter.step()
	return counter.get_steps()

class MiniSession extends RefCounted:
	var count: int = 0
	var total: int = 2
	var score: int = 0
	func advance() -> void:
		count += 1
	func is_done() -> bool:
		return count >= total
	func answer(is_right: bool) -> bool:
		if is_done():
			return false
		if is_right:
			score += 10
		return is_right


func run() -> int:
	var session := MiniSession.new()
	session.answer(true)
	session.advance()
	session.answer(false)
	session.advance()
	session.answer(true)
	return session.score
